const r = $('Google Business Profile Trigger').item.json;
const map = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
const stars = map[r.starRating] || Number(r.starRating) || 0;
const comment = (r.comment || '').trim();
return { json: {
  reviewId: r.reviewId,
  reviewerName: (r.reviewer && r.reviewer.displayName) || 'cliente',
  stars,
  comment,
  hasText: comment.length > 0,
  sentiment: stars >= 4 ? 'positiva' : 'negativa'
}};

